import numpy as np
from rdkit import Chem
m=Chem.MolFromMolFile('best.mol',sanitize=False,removeHs=False)
x=np.loadtxt('answer.xyz',skiprows=2,usecols=(1,2,3))
print('Bonds:')
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx();d=np.linalg.norm(x[i]-x[j]);
 if i<4 or i in [10,29,30,40,41,42] or not (0.95<d<1.9): print(i,j,round(d,3),b.GetBondType())
bonds={(min(b.GetBeginAtomIdx(),b.GetEndAtomIdx()),max(b.GetBeginAtomIdx(),b.GetEndAtomIdx())) for b in m.GetBonds()}
near=[]
for i in range(len(x)):
 for j in range(i):
  d=np.linalg.norm(x[i]-x[j])
  if (j,i) not in bonds and d<1.65: near.append((i,j,round(d,3),m.GetAtomWithIdx(i).GetSymbol()+m.GetAtomWithIdx(j).GetSymbol()))
print('Short nonbonded:',near)
print('Near Ru:',sorted([(round(np.linalg.norm(x[i]),3),i,m.GetAtomWithIdx(i).GetSymbol()) for i in range(1,len(x))])[:14])
# Render a validation view of the molecular structure.
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from mpl_toolkits.mplot3d import Axes3D
fig=plt.figure(figsize=(10,10));ax=fig.add_subplot(111,projection='3d')
colors={'C':'#555555','N':'#2266dd','P':'#f09b24','Cl':'#22bb44','Ru':'#bb4477','H':'#bbbbbb'}
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx();
 ax.plot(*x[[i,j]].T,color='#777777',lw=1 if m.GetAtomWithIdx(j).GetSymbol()=='H' else 2)
for el in colors:
 ids=[a.GetIdx() for a in m.GetAtoms() if a.GetSymbol()==el]
 ax.scatter(*x[ids].T,c=colors[el],s=20 if el=='H' else (150 if el=='Ru' else 70),depthshade=True)
 for i in ids:
  if el in ['P','Ru','N','Cl']: ax.text(*x[i],el)
ax.set_box_aspect((1,1,1)); ax.view_init(elev=20,azim=-70)
ax.set_xlabel('x (A)');ax.set_ylabel('y (A)');ax.set_zlabel('z (A)')
fig.tight_layout();fig.savefig('structure_check.png',dpi=150)
